use serde::{Serialize,Deserialize};
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Material{pub albedo:[f64;3],pub metallic:f64,pub roughness:f64}
#[derive(Clone,Debug,Serialize)]pub struct Brdf{pub diffuse:[f64;3],pub specular:[f64;3]}
fn dot(a:[f64;3],b:[f64;3])->f64{a.iter().zip(b).map(|(a,b)|a*b).sum()}
fn unit(v:[f64;3])->Result<[f64;3],String>{if v.iter().any(|v|!v.is_finite()){return Err("direction finite required".into());}let scale=v.iter().fold(0.0_f64,|s,v|s.max(v.abs()));if scale==0.0{return Err("direction nonzero required".into());}let q=v.map(|v|v/scale);let len=q[0].hypot(q[1]).hypot(q[2]);Ok(q.map(|v|v/len))}
/// BRDF (not multiplied by N.L). GGX metallic-roughness exactly as the glTF reference:
/// D_GGX (Trowbridge-Reitz), height-correlated Smith visibility V_GGX (Heitz 2014;
/// includes the 1/(4 N.L N.V) denominator), F_Schlick with f90=1, diffuse =
/// (1-metallic)(1-F) albedo/pi. Ported BY FORMULA (no code copied) from
/// github.com/KhronosGroup/glTF-Sample-Renderer source/Renderer/shaders/brdf.glsl
/// (Apache-2.0); the same forms ship in google/filament surface_brdf.fs (Apache-2.0)
/// as D_GGX / V_SmithGGXCorrelated / F_Schlick. This replaces the earlier UNCORRELATED
/// Smith product g1(nl)g1(nv)/(4 nl nv), which over-darkens grazing retro-reflection and
/// diverges from the glTF reference (pinned against an independent oracle below).
/// Known reference behavior kept verbatim: single scattering only (no Kulla-Conty
/// multi-scatter compensation) - rough metals measurably lose energy (directional
/// albedo 0.31 at metallic=1 roughness=1 normal incidence, analytic 1-ln2), and
/// grazing dielectrics can exceed 1 (measured 1.21 at roughness=0.3, thetav=80).
/// alpha is clamped to >= 0.001 per filament (MIN roughness guard, surface_brdf.fs).
/// Mirrored term-for-term in pbr_gpu.wgsl brdf().
pub fn sample(m:&Material,n:[f64;3],l:[f64;3],v:[f64;3])->Result<Brdf,String>{if m.albedo.iter().any(|v|!v.is_finite()||!(0.0..=1.0).contains(v))||!m.metallic.is_finite()||!(0.0..=1.0).contains(&m.metallic)||!m.roughness.is_finite()||!(0.001..=1.0).contains(&m.roughness){return Err("albedo/metallic0..1 roughness0.001..1 required".into());}let (n,l,v)=(unit(n)?,unit(l)?,unit(v)?);let (nl,nv)=(dot(n,l),dot(n,v));if nl<=0.0||nv<=0.0{return Ok(Brdf{diffuse:[0.;3],specular:[0.;3]});}let h=unit(std::array::from_fn(|i|l[i]+v[i]))?;let nh=dot(n,h).clamp(0.0,1.0);let vh=dot(v,h).clamp(0.0,1.0);let alpha=(m.roughness*m.roughness).max(0.001);let a2=alpha*alpha;let denominator=nh*nh*(a2-1.0)+1.0;let d=a2/(std::f64::consts::PI*denominator*denominator);let ggxv=nl*(nv*nv*(1.0-a2)+a2).sqrt();let ggxl=nv*(nl*nl*(1.0-a2)+a2).sqrt();let vis=if ggxv+ggxl>0.0{0.5/(ggxv+ggxl)}else{0.0};let f:[f64;3]=std::array::from_fn(|i|{let f0=0.04*(1.0-m.metallic)+m.albedo[i]*m.metallic;f0+(1.0-f0)*(1.0-vh).powi(5)});Ok(Brdf{diffuse:std::array::from_fn(|i|(1.0-m.metallic)*(1.0-f[i])*m.albedo[i]/std::f64::consts::PI),specular:f.map(|f|f*d*vis)})}
/// Raw nine-coefficient real SH evaluation, Y-up basis explicitly reported by tool.
/// Caller supplies irradiance coefficients, not unconvolved radiance. No specular IBL.
pub fn diffuse_sh(c:[[f64;3];9],normal:[f64;3])->Result<[f64;3],String>{if c.iter().flatten().any(|v|!v.is_finite()||v.abs()>1e9){return Err("bounded finite SH coefficients required".into());}let [x,y,z]=unit(normal)?;let b=[0.2820947918,0.4886025119*z,0.4886025119*y,0.4886025119*x,1.0925484306*x*z,1.0925484306*z*y,0.3153915653*(3.0*y*y-1.0),1.0925484306*x*y,0.5462742153*(x*x-z*z)];Ok(std::array::from_fn(|j|(0..9).map(|i|c[i][j]*b[i]).sum()))}

