 const ALBEDO:[f64;3]=[0.7,0.4,0.3];
 fn dir(theta_deg:f64,phi_deg:f64)->[f64;3]{let(t,p)=(theta_deg.to_radians(),phi_deg.to_radians());unit([t.sin()*p.cos(),t.sin()*p.sin(),t.cos()]).unwrap()}
 #[test]fn oracle_gltf_reference_math_exact(){
  for (m,r,label,l,v,dif,spec) in ORACLE{let b=sample(&Material{albedo:ALBEDO,metallic:*m,roughness:*r},[0.,0.,1.],*l,*v).unwrap();
   for j in 0..3{assert!((b.diffuse[j]-dif[j]).abs()<=1e-12*(1.+dif[j].abs()),"{label} m{m} r{r} diffuse[{j}]: {} vs oracle {}",b.diffuse[j],dif[j]);
    assert!((b.specular[j]-spec[j]).abs()<=1e-12*(1.+spec[j].abs()),"{label} m{m} r{r} specular[{j}]: {} vs oracle {}",b.specular[j],spec[j]);}}}
 #[test]fn reciprocity_swap_l_v(){
  for tl in [0.,15.,30.,60.,85.]{for tv in [0.,15.,30.,60.,85.]{for pl in [0.,90.,180.]{
   let(l,v)=(dir(tl,pl),dir(tv,0.));let m=Material{albedo:ALBEDO,metallic:0.4,roughness:0.35};
   let a=sample(&m,[0.,0.,1.],l,v).unwrap();let b=sample(&m,[0.,0.,1.],v,l).unwrap();
   for j in 0..3{assert!((a.diffuse[j]-b.diffuse[j]).abs()<1e-12,"diffuse reciprocity l{tl} v{tv} p{pl}");
    assert!((a.specular[j]-b.specular[j]).abs()<1e-12,"specular reciprocity l{tl} v{tv} p{pl}");}}}}}
 #[test]fn full_metallic_has_zero_diffuse_and_backfacing_is_zero(){
  let m=Material{albedo:ALBEDO,metallic:1.0,roughness:0.4};
  let b=sample(&m,[0.,0.,1.],dir(30.,0.),dir(45.,0.)).unwrap();assert_eq!(b.diffuse,[0.;3],"metallic=1 kills diffuse");
  let z=sample(&m,[0.,0.,1.],[0.,0.,-1.],[0.,0.,1.]).unwrap();assert_eq!((z.diffuse,z.specular),([0.;3],[0.;3]),"nl<=0 -> zero");
  let z2=sample(&m,[0.,0.,1.],[0.,0.,1.],[0.,0.,-1.]).unwrap();assert_eq!((z2.diffuse,z2.specular),([0.;3],[0.;3]),"nv<=0 -> zero");}
 #[test]fn grazing_geometry_stays_finite(){
  for r in [0.001,0.05,0.3,1.0]{for m in [0.,1.]{let b=sample(&Material{albedo:[1.;3],metallic:m,roughness:r},[0.,0.,1.],dir(89.9,0.),dir(89.9,180.)).unwrap();
   assert!(b.diffuse.iter().chain(b.specular.iter()).all(|v|v.is_finite()&&*v>=0.),"grazing finite+positive r{r} m{m}");}}}
 #[test]fn positivity_over_deterministic_grid(){
  for im in 0..5{for ir in 0..5{let m=im as f64/4.;let r=0.001+0.999*ir as f64/4.;
   for tl in [5.,25.,50.,75.,88.]{for tv in [5.,40.,70.,88.]{for pl in [0.,45.,120.,200.,310.]{
    let b=sample(&Material{albedo:ALBEDO,metallic:m,roughness:r},[0.,0.,1.],dir(tl,pl),dir(tv,0.)).unwrap();
    assert!(b.diffuse.iter().chain(b.specular.iter()).all(|v|v.is_finite()&&*v>=0.),"m{m} r{r} l{tl},{pl} v{tv}");}}}}}}
 // Directional-albedo (hemisphere) integral of (diffuse+specular)*nl, stratified
 // 360x180 quadrature. Expected values MEASURED with the independent Python oracle on
 // the same grid (NOT clamped to <=1: the reference math is single-scattering, so rough
 // metals lose energy and grazing dielectrics overshoot - documented on sample()).
 #[test]fn directional_albedo_matches_oracle_quadrature(){
  const CASES:&[(f64,f64,f64,f64)]=&[(0.,0.05,0.,1.003418),(0.,0.05,45.,0.964830),(0.,0.05,80.,0.946028),
   (0.,0.3,0.,0.999558),(0.,0.3,45.,1.001014),(0.,0.3,80.,1.210911),
   (0.,1.,0.,0.972231),(0.,1.,45.,0.974233),(0.,1.,80.,0.986143),
   (1.,0.05,0.,1.087344),(1.,0.05,45.,0.154243),(1.,0.05,80.,0.005485),
   (1.,0.3,0.,0.990715),(1.,0.3,45.,0.985365),(1.,0.3,80.,0.881727),
   (1.,1.,0.,0.306854),(1.,1.,45.,0.376776),(1.,1.,80.,0.668191)];
  let m_wh=Material{albedo:[1.;3],metallic:0.,roughness:0.5};
  for (met,rough,tv,expect) in CASES{let m=Material{metallic:*met,roughness:*rough,..m_wh.clone()};let v=dir(*tv,0.);
   let mut acc=0.;let(nt,np)=(360usize,180usize);
   for it in 0..nt{let th=(it as f64+0.5)/nt as f64*std::f64::consts::FRAC_PI_2;
    for ip in 0..np{let ph=(ip as f64+0.5)/np as f64*std::f64::consts::TAU;
     let l=[th.sin()*ph.cos(),th.sin()*ph.sin(),th.cos()];
     let b=sample(&m,[0.,0.,1.],l,v).unwrap();
     acc+=(b.diffuse[0]+b.specular[0])*th.cos()*th.sin();}}
   let e=acc*std::f64::consts::FRAC_PI_2/nt as f64*std::f64::consts::TAU/np as f64;
   assert!((e-expect).abs()<5e-4,"m{met} r{rough} tv{tv}: integral {e} vs oracle {expect}");}}
 #[test]fn validation_errors_are_typed(){
  let n=[0.,0.,1.];
  assert_eq!(sample(&Material{albedo:[0.5,1.2,0.5],metallic:0.,roughness:0.5},n,n,n).err().unwrap(),"albedo/metallic0..1 roughness0.001..1 required");
  assert_eq!(sample(&Material{albedo:[0.5;3],metallic:f64::NAN,roughness:0.5},n,n,n).err().unwrap(),"albedo/metallic0..1 roughness0.001..1 required");
  assert_eq!(sample(&Material{albedo:[0.5;3],metallic:0.,roughness:0.0},n,n,n).err().unwrap(),"albedo/metallic0..1 roughness0.001..1 required");
  assert_eq!(sample(&Material{albedo:[0.5;3],metallic:0.,roughness:0.5},[0.;3],n,n).err().unwrap(),"direction nonzero required");}
